import pathlib
root = pathlib.Path('/home/andrew/Projects/scrapkeep-wt-PS-04')

def edit(path, pairs):
    p = root / path
    t = p.read_text()
    for old, new in pairs:
        assert t.count(old) == 1, (path, old[:70], t.count(old))
        t = t.replace(old, new)
    p.write_text(t)
    print(path, len(pairs), 'edits')

